// Legacy session + transformMessages-style plain-key deletes, plus
// process.env cleanup, under checked-dynamic receivers. Object values
// start as JSON.parse results so they ride the checked-dynamic tree.
export function scrubLegacySession() {
  const entry = JSON.parse(
    JSON.stringify({
      type: "compaction",
      firstKeptEntryIndex: 1,
      keep: "yes",
    }),
  );
  const before = Object.keys(entry).join("+");
  delete entry.firstKeptEntryIndex;
  const after = Object.keys(entry).join("+");
  const envKey = "SCRIPTC_NPM_DELETE_ENV";
  process.env[envKey] = "1";
  const had = process.env[envKey] !== undefined;
  delete process.env[envKey];
  const cleared = process.env[envKey] === undefined;
  return [before, after, had ? "env-set" : "env-miss", cleared ? "env-cleared" : "env-stale"].join("|");
}

export function transformMessagesShape() {
  const toolCall = JSON.parse(
    JSON.stringify({
      id: "tc",
      name: "tool",
      thoughtSignature: "sig",
      partialJson: "{",
      args: { n: 1 },
    }),
  );
  delete toolCall.thoughtSignature;
  delete toolCall.partialJson;
  return [Object.keys(toolCall).join(","), JSON.stringify(toolCall)].join("|");
}
